-- Bước 1: Thêm cột mới với kiểu TEXT
            ALTER TABLE payment_request
                ADD COLUMN content_text TEXT;

-- Bước 2: Sao chép dữ liệu từ cột cũ sang cột mới
            UPDATE payment_request
            SET content_text = content;

-- Bước 3: Xóa cột cũ
            ALTER TABLE payment_request
            DROP COLUMN content;

-- Bước 4: Đổi tên cột mới thành tên ban đầu
            ALTER TABLE payment_request
                RENAME COLUMN content_text TO content;

